COST = {"EMPTY": 0, "K1": 0, "K2": 0, "V": 0, "W": 5, "T_W": 25, "ICE": 10, "PIT": 40, "CRACK": 20,
        "SWITCH": 30, "R_GATE": 20, "B_GATE": 20, "TNT": 40, "BOX": 30, "HEAL": 30, "MIMIC": 60,
        "PLATE": 45, "P_GATE": 30}
for k in ("MIRROR_NE", "MIRROR_SE", "MIRROR_SW", "MIRROR_NW"): COST[k] = 25
